rules_version = '2';
service cloud.firestore {
  match /databases/{database}/documents {

    // ATALHO TÁTICO: Centraliza a identificação do Comandante
    function isAdmin() {
      return request.auth != null && request.auth.token.email == 'ccbteodoro@gmail.com';
    }

    // 1. Dicionário de Movimentos (IA)
    match /dicionario/{docId} {
      allow read: if request.auth != null;
      allow write: if isAdmin(); // Apenas o Comandante altera a base de movimentos
    }

    // 2. Treinos Concluídos (Coleção Raiz)
    match /treinos_concluidos/{docId} {
      // O atleta vê os próprios treinos; o Comandante vê todos
      allow read: if request.auth != null && (resource.data.userId == request.auth.uid || isAdmin());
      // O atleta só cria, altera ou apaga registos assinados com o seu próprio UID
      allow create: if request.auth != null && request.auth.uid == request.resource.data.userId;
      allow update, delete: if request.auth != null && request.auth.uid == resource.data.userId;
    }

    // 3. Jogadores (Perfil, Ranking PvP da Arena)
    match /jogadores/{userId} {
      allow read: if request.auth != null; // Leitura pública para o Ranking funcionar
      allow write: if request.auth != null && request.auth.uid == userId; // O atleta atualiza a própria pontuação

      // 3.1. Subcoleção: Dossiê de Combate (Gráficos do Painel Admin)
      match /treinos_concluidos/{docId} {
        allow read: if request.auth != null && (request.auth.uid == userId || isAdmin());
        allow write: if request.auth != null && request.auth.uid == userId;
      }
    }

    // 4. Cofre de Campanha Pessoal (Mesociclos e Preferências)
    match /usuarios/{userId} {
      allow read, write: if request.auth != null && request.auth.uid == userId;
    }

    // 5. REGRA DE CONTENÇÃO (Catch-All)
    // Fecha todas as portas que não foram explicitamente abertas acima
    match /{document=**} {
      allow read, write: if false;
    }
  }
}
